query:
SELECT ?technologyCategory ?responseType ?participants WHERE {
  ?entry a survey:OrderCancellation ;
    survey:forTechnologyCategory ?tech ;
    survey:hasResponseType ?responseType ;
    survey:participantCount ?participants .
  BIND(REPLACE(REPLACE(REPLACE(STR(?tech), '^.*/OrderCancellationChange_Semi_', ''), 'lt%3D_7nm', '<=_7nm'), '_to_lt', '_to_<') AS ?technologyCategory)
}
ORDER BY ?technologyCategory ?responseType

SELECT ?companyName ?totalCount WHERE {
  {
    SELECT (COUNT(?c2) AS ?totalCount) WHERE {
      ?c2 a survey:Company ; survey:hasSurveyOrigin ?o2 ; survey:reportsShortage false .
      ?o2 a survey:Tier1_Survey .
    }
  }
  ?c a survey:Company ; survey:companyName ?companyName ; survey:hasSurveyOrigin ?o ; survey:reportsShortage false .
  ?o a survey:Tier1_Survey .
}
ORDER BY ?companyName

SELECT ?companyName ?totalCount WHERE {
  {
    SELECT (COUNT(?c2) AS ?totalCount) WHERE {
      ?c2 a survey:Company ; survey:hasSurveyOrigin ?o2 ; survey:reportsShortage true .
      ?o2 a survey:Semiconductor_Survey .
    }
  }
  ?c a survey:Company ; survey:companyName ?companyName ; survey:hasSurveyOrigin ?o ; survey:reportsShortage true .
  ?o a survey:Semiconductor_Survey .
}
ORDER BY ?companyName

SELECT ?technologyCategory ?responseType (SUM(xsd:integer(?cnt)) AS ?responses) WHERE {
  ?oc a survey:OrderCancellation ;
    survey:forTechnologyCategory ?tech ;
    survey:hasResponseType ?responseType ;
    survey:participantCount ?cnt .
  BIND(REPLACE(REPLACE(REPLACE(STR(?tech), '^.*/OrderCancellationChange_Semi_', ''), 'lt%3D_7nm', '<=_7nm'), '_to_lt', '_to_<') AS ?technologyCategory)
}
GROUP BY ?technologyCategory ?responseType
ORDER BY ?technologyCategory ?responseType

SELECT ?componentLabel (COUNT(?entry) AS ?entryCount) WHERE {
  ?entry a survey:InventoryDevelopment_Tier1 ;
    survey:forComponent ?component ;
    survey:inventoryTrend ?trend .
  BIND(REPLACE(STR(?component), '^.*/', '') AS ?componentLabel)
}
GROUP BY ?componentLabel
ORDER BY ?componentLabel

SELECT ?vehicleType (AVG(?percentage) AS ?avgPercentage) WHERE {
  ?entry a survey:AutonomousDrivingDevelopment ;
    survey:hasVehicleType ?vehicle ;
    survey:hasPercentage ?percentage .
  BIND(REPLACE(STR(?vehicle), '^.*/', '') AS ?vehicleType)
}
GROUP BY ?vehicleType
ORDER BY ?vehicleType

SELECT ?componentLabel (COUNT(?entry) AS ?entryCount) WHERE {
  ?entry a survey:InventoryDevelopment_Tier1 ;
    survey:forComponent ?component ;
    survey:inventoryTrend ?trend .
  BIND(REPLACE(STR(?component), '^.*/', '') AS ?componentLabel)
}
GROUP BY ?componentLabel
ORDER BY ?componentLabel

SELECT ?vehicle ?saeLabel (AVG(?pct) AS ?avgPct) WHERE {
  survey:AutonomousDrivingDevelopment_Tier1 survey:hasDetail ?entry .
  ?entry a survey:AutonomousDrivingDevelopment ;
    survey:hasVehicleType ?veh ;
    survey:hasSAELevel ?sae ;
    survey:hasPercentage ?pct .
  BIND(IF(CONTAINS(STR(?veh), 'BEV'), 'BEV', IF(CONTAINS(STR(?veh), 'BEHV'), 'BEHV', IF(CONTAINS(STR(?veh), 'ICE'), 'ICE', 'OTHER'))) AS ?vehicle)
  FILTER(?vehicle != 'OTHER')
  BIND(STRAFTER(STR(?sae), 'SAE_Level_') AS ?saeLabel)
}
GROUP BY ?vehicle ?saeLabel
ORDER BY ?vehicle xsd:integer(?saeLabel)
